def seed_threat_sources(apps, schema_editor):
    """Seed 4 ThreatSource rows from NIST SP 800-30r1."""
    ThreatSource = apps.get_model("threats", "ThreatSource")
    seeds = [
        {
            "slug": "adversarial",
            "name": "Adversarial",
            "description": "Individuals, groups, organizations, or states that seek to exploit dependence on cyber resources.",
        },
        {
            "slug": "accidental",
            "name": "Accidental",
            "description": "Erroneous actions taken by individuals in the course of executing their everyday responsibilities.",
        },
        {
            "slug": "structural",
            "name": "Structural",
            "description": "Failures of equipment, environmental controls, or software due to aging, resource depletion, or other circumstances which exceed expected operating parameters.",
        },
        {
            "slug": "environmental",
            "name": "Environmental",
            "description": "Natural disasters and failures of critical infrastructure on which the organization depends but which are outside the control of the organization.",
        },
    ]
    for seed in seeds:
        ThreatSource.objects.get_or_create(slug=seed["slug"], defaults=seed)


def reverse_seed(apps, schema_editor):
    ThreatSource = apps.get_model("threats", "ThreatSource")
    ThreatSource.objects.filter(
        slug__in=["adversarial", "accidental", "structural", "environmental"]
    ).delete()


